from typing import Any, Iterator
import csv
import io
import zipfile
from openpyxl import load_workbook
from openpyxl.utils.exceptions import InvalidFileException
REQUIRED_COLUMNS = ('name', 'email', 'role')
VALID_ROLES = ('admin', 'editor', 'viewer')
MAX_ROWS = 10000
MAX_EMAIL_LENGTH = 254


def _read_xlsx(content: bytes, max_rows: int) -> tuple[list[str], list[tuple[int, dict[Any, Any]]]]:
    workbook = load_workbook(io.BytesIO(content), read_only=True, data_only=True)
    try:
        lines = workbook.active.iter_rows(max_row=max_rows + 2, values_only=True)
        first = next(lines, None)
        if first is None:
            return ([], [])
        header = [('' if v is None else str(v)) for v in first]
        rows = []
        for number, values in enumerate(lines, 2):
            cells = ['' if v is None else str(v).strip() for v in values]
            row = dict(zip(header, cells))
            row = {**{h: '' for h in header}, **row}
            if len(cells) > len(header) and any(cells[len(header):]):
                row[None] = cells[len(header):]
            rows.append((number, row))
        return (header, rows)
    finally:
        workbook.close()


